1	// What a check does when it fails: `block` fails the run (and denies the call, for
2	// an action guard), `advise` reports and lets it through. A project's per-rule
3	// override in settings takes these two values or `off`.
4	export const ON_FAIL = Object.freeze(['block', 'advise']);
5	
6	// The field's previous spelling, `severity: "blocking" | "advisory"`, read on a
7	// rule, a declaration, a finding and a settings override alike. A member's own
8	// local packs and settings still hold it until it acts on `legacy-shape-in-use`,
9	// and a canon pack version predating the rename runs beside this engine for the
10	// window between the engine's update and that pack's.
11	// @legacy-tolerance advisory:legacy-shape-in-use retire:#2319
12	export const LEGACY_ON_FAIL = Object.freeze({ blocking: 'block', advisory: 'advise' });
13	
14	// The on_fail a rule, declaration, finding or override value means, or undefined
15	// when it says neither - unknown is left unknown rather than defaulted.
16	export function onFailOf(x) {
17	  if (typeof x === 'string') return ON_FAIL.includes(x) ? x : LEGACY_ON_FAIL[x];
18	  if (ON_FAIL.includes(x?.on_fail)) return x.on_fail;
19	  return LEGACY_ON_FAIL[x?.severity];
20	}
21	
22	// A finding also carries its on_fail in the old spelling, because a member's own
23	// tests may read `finding.severity` and would break on the engine update rather than
24	// on anything the member did; it comes out with the rest of the tolerance.
25	// @legacy-tolerance advisory:none retire:#2319
26	const LEGACY_SEVERITY_MIRROR = Object.freeze({ block: 'blocking', advise: 'advisory' });
27	
28	// The finding failing as `onFail`, in both spellings.
29	export const failingAs = (f, onFail) => ({ ...f, on_fail: onFail, severity: LEGACY_SEVERITY_MIRROR[onFail] });
30	
31	// A finding in the current shape, whichever spelling it was built with.
32	const normalized = (f) => failingAs(f, onFailOf(f));
33	
34	// The words a report prints for each value: a finding still reads as blocking or
35	// advisory, and the usage fold counts findings by those words.
36	const REPORT_LABEL = { block: 'BLOCKING', advise: 'ADVISORY' };
37	
38	export function finding(rule, { file, line = null, what, fix, why = null, on_fail = null, severity = null }) {
39	  return failingAs({
40	    rule: rule.id,
41	    file,
42	    line,
43	    what,
44	    why: why || rule.why,
45	    fix,
46	    doc: rule.doc,
47	    // The rule's declared creation date, carried onto every finding so the grace
48	    // window below can be applied by the scope-blind reporter, which never sees
49	    // the rules themselves. Undefined on a rule that declared none — see `applyGrace`.
50	    since: rule.since,
