// Dependency-free by design: a local pack's checks must load without the
// vendored mount, so this returns plain finding objects rather than importing
// engine/checks/helpers/findings.mjs.

// One package.json marks the whole ES-module tree — `site/package.json` — and
// the repo root carries the project's own. A third one is a copy of that
// pattern into a directory the second already covers, and buys nothing.

const ALLOWED = new Set(['package.json', 'site/package.json']);

const rule = {
  id: 'edfringe-no-stray-package-json',
  on_fail: 'advise',
  description: 'No package.json exists outside the repo root and site/, which declares the ES-module tree',
  why:
    'site/package.json already declares every source under it an ES module, so a package.json in one of its subdirectories re-states what it inherits — and one outside site/ marks a tree that has no module type to declare',
  doc: 'RULES.md',

  run(ctx) {
    const stray = ctx.files.filter((f) => f.endsWith('/package.json') && !ALLOWED.has(f)).sort();
    if (stray.length === 0) return [];

    return stray.map((f) => finding(f,
      `${f} adds nothing site/package.json does not already give its directory — remove it, unless it genuinely configures its own dependencies/scripts`,
    ));
  },
};

function finding(file, fix) {
  return {
    rule: rule.id,
    severity: rule.severity,
    file,
    line: null,
    what: `${file} is a package.json outside the repo root and site/`,
    why: rule.why,
    fix,
    doc: rule.doc,
  };
}

export default rule;

// Dependency-free by design: a local pack's checks must load without the
// vendored mount, so this returns plain finding objects rather than importing
// engine/checks/helpers/findings.mjs.

const VERIFY = 'scripts/verify.sh';
const NORMALIZER = 'scraper/normalize.py';
const SELFTEST = '--selftest';

// Scoped parse rather than a grep: verify.sh labels the step
// `step "Normalizer self-test — normalize.py --selftest"`, so a plain grep for
// the two tokens passes even after the real invocation is deleted — the label
// alone would satisfy it. Drop comment lines and the quoted argument of every
// `step` call, then look for a surviving command line.
function commandLines(sh) {
  return sh
    .split('\n')
    .filter((l) => !/^\s*#/.test(l))
    .map((l) => l.replace(/\bstep\s+(["'])(?:(?!\1).)*\1/g, ''))
    // A trailing comment can carry the tokens too (`node --check  # not normalize.py --selftest`).
    .map((l) => l.replace(/\s#.*$/, ''));
}

const rule = {
  id: 'edfringe-normalizer-selftest-in-verify',
  on_fail: 'block',
  description: "scripts/verify.sh runs the normalizer's offline self-test (python3 scraper/normalize.py --selftest)",
  why:
    "the live edfringe API is unreachable from a session, so the normalizer self-test is the ONE transform check that runs offline — drop it from the gate and every scraper change ships with no verification at all, in a repo where nothing else can stand in for it",
  doc: 'RULES.md',

  run(ctx) {
    // Relevance-first: no normalizer, or one with no self-test to run, is not
    // this rule's business.
    if (!ctx.files.includes(NORMALIZER)) return [];
    const normalizer = ctx.read(NORMALIZER);
    if (normalizer === null || !normalizer.includes(SELFTEST)) return [];

    const sh = ctx.files.includes(VERIFY) ? ctx.read(VERIFY) : null;
    if (sh === null) return []; // relevance-first: no verification gate in this tree

    const wired = commandLines(sh).some((l) => l.includes('normalize.py') && l.includes(SELFTEST));
    if (wired) return [];

    return [{
      rule: rule.id,
      severity: rule.severity,
      file: VERIFY,
      line: null,
      what: `${NORMALIZER} supports ${SELFTEST} but ${VERIFY} never invokes it (a step label naming it does not count — only a command line does)`,
      why: rule.why,
      fix: `restore the step to ${VERIFY}: \`python3 ${NORMALIZER} ${SELFTEST}\` — both the pre-commit hook and CI run that script, so this is the only place wiring it makes it a gate`,
      doc: rule.doc,
    }];
  },
};

export default rule;

// Dependency-free by design: a local pack's checks must load without the
// vendored mount, so this returns plain finding objects rather than importing
// engine/checks/helpers/findings.mjs.

const PKG = 'package.json';
const VERIFY = 'scripts/verify.sh';

// The `node --test <globs...>` invocation, wherever it appears in a shell script
// or a package.json script string. Anchored per line so verify.sh's prose
// comments above it can mention the command without matching.
const NODE_TEST = /^\s*node --test\s+(.+?)\s*$/m;

// If verify.sh delegates to the package script instead of repeating the globs,
// there is one source of truth and nothing to drift — the check stands down.
const DELEGATES = /\bnpm (?:run )?test\b/;

const rule = {
  id: 'edfringe-test-globs-in-step',
  on_fail: 'block',
  description:
    'The `node --test` file globs in package.json\'s "test" script and in scripts/verify.sh name the same set of test files',
  why:
    'CI and the pre-commit hook run scripts/verify.sh while a developer runs `npm test`, so the same list is spelled twice; a glob added to only one of them means a suite that is green locally and never runs in CI, or one that runs in CI and is invisible to whoever is editing it',
  doc: 'scripts/verify.sh',

  run(ctx) {
    const pkgRaw = ctx.read(PKG);
    const verifyRaw = ctx.read(VERIFY);
    // Relevance-first: a tree without both files has no duplication to guard.
    if (pkgRaw === null || verifyRaw === null) return [];

    let pkg;
    try {
      pkg = JSON.parse(pkgRaw);
    } catch {
      return []; // not this check's business — JSON validity is caught elsewhere
    }

    const script = pkg?.scripts?.test;
    if (typeof script !== 'string') return [];

    const pkgMatch = NODE_TEST.exec(script);
    const verifyMatch = NODE_TEST.exec(verifyRaw);

    // Neither side runs `node --test` from here: nothing is duplicated.
    if (!pkgMatch && !verifyMatch) return [];

    if (pkgMatch && !verifyMatch) {
      if (DELEGATES.test(verifyRaw)) return []; // single-sourced through `npm test`
      return [finding(
        `package.json's "test" script runs \`node --test\` but ${VERIFY} runs no unit tests at all`,
        `add the \`node --test\` line back to ${VERIFY}, or have it call \`npm test\` so the globs live in one place`,
      )];
    }
    if (verifyMatch && !pkgMatch) {
      return [finding(
        `${VERIFY} runs \`node --test\` but package.json's "test" script does not`,
        `point package.json's "test" script at the same globs, or at \`bash ${VERIFY}\``,
      )];
    }

    const inPkg = globs(pkgMatch[1]);
    const inVerify = globs(verifyMatch[1]);
    const onlyPkg = inPkg.filter((g) => !inVerify.includes(g));
    const onlyVerify = inVerify.filter((g) => !inPkg.includes(g));
    if (onlyPkg.length === 0 && onlyVerify.length === 0) return [];

    const parts = [];
    if (onlyPkg.length) parts.push(`only in package.json: ${onlyPkg.join(' ')}`);
    if (onlyVerify.length) parts.push(`only in ${VERIFY}: ${onlyVerify.join(' ')}`);
    return [finding(
      `the \`node --test\` globs have drifted apart — ${parts.join('; ')}`,
      `add the missing glob to both lines (they are meant to be identical), or have ${VERIFY} call \`npm test\` so there is only one list`,
    )];
  },
};

/** The whitespace-separated glob arguments, order-insensitive and de-duped. */
function globs(args) {
  return [...new Set(args.split(/\s+/).filter(Boolean))].sort();
}

function finding(what, fix) {
  return {
    rule: rule.id,
    severity: rule.severity,
    file: VERIFY,
    line: null,
    what,
    why: rule.why,
    fix,
    doc: rule.doc,
  };
}

export default rule;

// Dependency-free by design: a local pack's checks must load without the
// vendored mount, so this returns plain finding objects rather than importing
// engine/checks/helpers/findings.mjs.

const VERIFY = 'scripts/verify.sh';

// The `git ls-files 'site' 'scripts' …` call in verify.sh's "JavaScript
// syntax" step — captures its quoted top-level-directory arguments.
const LS_FILES_DIRS = /git ls-files((?:\s+'[^']*')+)/;
const JS_FILE = /\.m?js$/;

const rule = {
  id: 'edfringe-verify-sh-covers-source-dirs',
  on_fail: 'block',
  description:
    'scripts/verify.sh\'s JavaScript syntax-check step names every top-level directory that has committed .js/.mjs source',
  why:
    'the step only walks the top-level directories named in its `git ls-files` call; a source directory left off that list is silently never parse-checked, in the pre-commit hook or in CI',
  doc: 'RULES.md',

  run(ctx) {
    const verifyRaw = ctx.read(VERIFY);
    if (verifyRaw === null) return []; // relevance-first: no gate script, nothing to check

    const m = LS_FILES_DIRS.exec(verifyRaw);
    const listed = new Set((m ? m[1].match(/'([^']*)'/g) : []).map((s) => s.slice(1, -1)));

    const present = new Set();
    for (const f of ctx.files) {
      if (!JS_FILE.test(f)) continue;
      const slash = f.indexOf('/');
      if (slash === -1) continue; // a bare top-level file, not inside a directory
      const top = f.slice(0, slash);
      if (top.startsWith('.')) continue; // hidden/tooling dirs (.claudinite, .github, ...) are out of scope
      present.add(top);
    }

    const missing = [...present].filter((d) => !listed.has(d)).sort();
    if (missing.length === 0) return [];

    const plural = missing.length > 1;
    return [finding(
      `${missing.join(', ')} ${plural ? 'have' : 'has'} committed .js/.mjs files but ${plural ? "aren't" : "isn't"} named in ${VERIFY}'s \`git ls-files\` syntax-check step`,
      `add ${missing.map((d) => `'${d}'`).join(' ')} to the \`git ls-files\` call in ${VERIFY} — or, if the directory is deliberately excluded (vendored/generated content), extend its grep -v filter instead`,
    )];
  },
};

function finding(what, fix) {
  return {
    rule: rule.id,
    severity: rule.severity,
    file: VERIFY,
    line: null,
    what,
    why: rule.why,
    fix,
    doc: rule.doc,
  };
}

export default rule;

// Dependency-free by design: a local pack's checks must load without the
// vendored mount, so this returns plain finding objects rather than importing
// engine/checks/helpers/findings.mjs.

// A local task's worker script: .claudinite/local/packs/<pack>/tasks/<task>/worker.sh
// (the legacy .claudinite/local_packs/ path is accepted during the rename window).
const WORKER = /^\.claudinite\/local(?:\/packs|_packs)\/[^/]+\/tasks\/[^/]+\/worker\.sh$/;

// The writing acts this check cares about — a worker that only reads can be left
// wherever the scheduler put it.
const WRITES = /^[^#\n]*\bgit\s+(?:commit|push)\b/m;

// Restoring the checkout: `git checkout main` / `git switch main`, ignoring comments.
const RESTORES = /^[^#\n]*\bgit\s+(?:checkout|switch)\s+main\b/m;

const rule = {
  id: 'edfringe-worker-restores-main',
  on_fail: 'block',
  description:
    'a local task worker that commits or pushes returns the checkout to `main` first',
  why:
    'the Claudinite scheduler runs every due task in ONE checkout, and a task ordered after a delivering `basics/baselining` inherits the maintenance branch its deliver() left behind (`git checkout -B`, never switched back) — an upstream-less branch whose bare push aborts with exit 128, which is how #141 and #231 each silently stopped a data refresh for days',
  doc: 'RULES.md',

  run(ctx) {
    const findings = [];

    for (const file of ctx.files) {
      if (!WORKER.test(file)) continue;

      const src = ctx.read(file);
      if (src === null) continue; // relevance-first: unreadable, not this check's business

      const write = WRITES.exec(src);
      if (!write) continue; // a read-only worker cannot lose a commit to the wrong branch

      const restore = RESTORES.exec(src);

      if (!restore) {
        findings.push(finding(
          file,
          'commits or pushes without ever returning the checkout to `main`',
        ));
        continue;
      }

      if (restore.index > write.index) {
        findings.push(finding(
          file,
          'returns the checkout to `main` only after it has already committed or pushed',
        ));
      }
    }

    return findings.sort((a, b) => a.file.localeCompare(b.file));
  },
};

function finding(file, what) {
  return {
    rule: rule.id,
    severity: rule.severity,
    file,
    line: null,
    what: `${file} ${what}`,
    why: rule.why,
    fix:
      'before the worker writes anything, add the guard the refresh-shows / refresh-tickets workers carry: ' +
      'read `git rev-parse --abbrev-ref HEAD` and `git checkout main` when it is anything else. ' +
      'Do not reach for `git push origin HEAD:main` instead — from a polluted checkout that pushes ' +
      "baselining's unreviewed converge straight to main, past its own maintenance PR.",
    doc: rule.doc,
  };
}

export default rule;

// Dependency-free by design: a local pack's checks must load without the
// vendored mount, so this returns plain finding objects rather than importing
// engine/checks/helpers/findings.mjs.

const DAY_FILE = /^site\/data\/days\/\d{4}-\d{2}-\d{2}\.json$/;
const MASTER = 'site/data/normalized/shows.min.json';
const AVAILABILITY = 'site/data/normalized/availability.min.json';
const LOOKUPS = 'site/data/venues.json';

// Per file, so one systematically shifted lookup list reports a readable handful
// instead of thousands of identical lines.
const MAX_PER_FILE = 5;

const rule = {
  id: 'edfringe-lookup-indices',
  on_fail: 'block',
  description:
    'Every genre / room / subgenre / ticket-status / age-restriction index in the committed day files and shows.min.json resolves inside the matching data/venues.json lookup list, and every status index in availability.min.json resolves inside that file\'s own list',
  why:
    'the wire format ships the lookup lists once and references them by position, so an index the list no longer has (or a list regenerated without its day files) mislabels shows silently — the client renders undefined, or worse, the neighbouring genre',
  doc: 'scraper/README.md',

  run(ctx) {
    const raw = ctx.read(LOOKUPS);
    if (raw === null) return []; // relevance-first: no data layer in this repo state

    let lookups;
    try {
      lookups = JSON.parse(raw);
    } catch (e) {
      return [finding(LOOKUPS, `data/venues.json is not valid JSON: ${e.message}`,
        'regenerate it with `python3 scraper/normalize.py` rather than hand-editing')];
    }

    const out = [];
    const len = (name) => (Array.isArray(lookups[name]) ? lookups[name].length : 0);

    // The producer is scraper/normalize.py (build_day_files / minify_master); the
    // consumers are js/app.js adaptShow and plan/lib/hydrate.js rehydrateShows.
    // Day-file field -> venues.json list. `room` and `ts` carry -1 for "unknown"
    // (normalize.py writes -1; adaptShow resolves it to no room / no status).
    const dayFields = [
      ['genre', 'genres', false],
      ['room', 'rooms', true],
      ['ts', 'ticketStatuses', true],
    ];
    // shows.min.json's shorter keys, same lists. No ticket status here: it moved
    // to availability.min.json so the catalogue could stop changing with it (#249),
    // and it is checked separately below against that file's own status list.
    const masterFields = [
      ['g', 'genres', false],
      ['rm', 'rooms', true],
      ['ar', 'ageRestrictions', true],
    ];

    function finding(file, what, fix) {
      return {
        rule: rule.id,
        severity: rule.severity,
        file,
        line: null,
        what,
        why: rule.why,
        fix,
        doc: rule.doc,
      };
    }

    function checkIndex(found, label, value, list, allowMissing) {
      if (value === undefined || value === null) return;
      if (!Number.isInteger(value)) {
        found.push([label, `${label} is ${JSON.stringify(value)}, not an integer index`]);
        return;
      }
      if (allowMissing && value === -1) return;
      if (value < 0 || value >= len(list)) {
        found.push([label, `${label} = ${value} is outside venues.json "${list}" (${len(list)} entries)`]);
      }
    }

    function checkRecords(file, records, fields, subKey) {
      const found = [];
      records.forEach((rec, i) => {
        if (found.length >= MAX_PER_FILE) return;
        if (!rec || typeof rec !== 'object') return;
        const at = `record #${i}${rec.title ? ` (${rec.title})` : rec.t ? ` (${rec.t})` : ''}`;
        for (const [key, list, allowMissing] of fields) {
          checkIndex(found, `${at} ${key}`, rec[key], list, allowMissing);
        }
        for (const s of rec[subKey] ?? []) {
          checkIndex(found, `${at} ${subKey}[]`, s, 'subgenres', false);
        }
      });
      for (const [, what] of found.slice(0, MAX_PER_FILE)) {
        out.push(finding(file, what,
          'regenerate the data layer together — `python3 scraper/normalize.py` (add --merge for a top-up) rewrites venues.json and every day file from the master in one pass; never edit either side alone'));
      }
    }

    for (const file of ctx.files.filter((f) => DAY_FILE.test(f))) {
      const text = ctx.read(file);
      if (text === null) continue;
      let records;
      try {
        records = JSON.parse(text);
      } catch (e) {
        out.push(finding(file, `day file is not valid JSON: ${e.message}`,
          'regenerate it with `python3 scraper/normalize.py`'));
        continue;
      }
      if (!Array.isArray(records)) {
        out.push(finding(file, 'a day file must be a plain array of show records',
          'regenerate it with `python3 scraper/normalize.py`'));
        continue;
      }
      // A day record is one performance: its ticket status is the flat `ts`,
      // already covered by dayFields, so no per-performance list here.
      checkRecords(file, records, dayFields, 'subs');
    }

    const masterText = ctx.files.includes(MASTER) ? ctx.read(MASTER) : null;
    if (masterText !== null) {
      let records;
      try {
        records = JSON.parse(masterText);
      } catch (e) {
        out.push(finding(MASTER, `shows.min.json is not valid JSON: ${e.message}`,
          'regenerate it with `python3 scraper/normalize.py`'));
        return out;
      }
      if (Array.isArray(records)) {
        checkRecords(MASTER, records, masterFields, 'sg');
      }
    }

    // The availability sidecar indexes into its OWN `ts` list, not venues.json —
    // it is rewritten by refresh-tickets on its own and must not depend on the
    // lookup file having been regenerated in the same breath. Same failure mode,
    // though: a status index the list no longer has relabels a performance's
    // availability silently.
    const availText = ctx.files.includes(AVAILABILITY) ? ctx.read(AVAILABILITY) : null;
    if (availText !== null) {
      let sidecar;
      try {
        sidecar = JSON.parse(availText);
      } catch (e) {
        out.push(finding(AVAILABILITY, `availability.min.json is not valid JSON: ${e.message}`,
          'regenerate it with `python3 scraper/normalize.py --minify-from-master`'));
        return out;
      }
      const statuses = Array.isArray(sidecar && sidecar.ts) ? sidecar.ts : [];
      const found = [];
      for (const [showId, byKey] of Object.entries((sidecar && sidecar.a) || {})) {
        if (found.length >= MAX_PER_FILE) break;
        for (const [key, value] of Object.entries(byKey || {})) {
          if (!Number.isInteger(value)) {
            found.push(`${showId} ${key} is ${JSON.stringify(value)}, not an integer index`);
          } else if (value < 0 || value >= statuses.length) {
            found.push(`${showId} ${key} = ${value} is outside this file's own "ts" (${statuses.length} entries)`);
          }
          if (found.length >= MAX_PER_FILE) break;
        }
      }
      for (const what of found.slice(0, MAX_PER_FILE)) {
        out.push(finding(AVAILABILITY, what,
          'regenerate the data layer together — `python3 scraper/normalize.py --minify-from-master` rewrites the sidecar and its status list from the master in one pass; never edit either side alone'));
      }
    }

    return out;
  },
};

export default rule;

